using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Xml.Linq;
class Check {
// METHODS
static void Main(){var empty=RebirthRecipeDiscoveryPolicy.Read(XElement.Parse("<recipeDiscoveryPolicy version='1'/>"));if(empty.RequiresReading("knowledge.recipe"))throw new Exception("Empty policy publishes read markers");if(!empty.Allows("example",null))throw new Exception("Empty policy changed eligibility");var policy=RebirthRecipeDiscoveryPolicy.Read(XElement.Parse("<recipeDiscoveryPolicy version='1'><recipe name='example' requires_read='knowledge.recipe'/></recipeDiscoveryPolicy>"));if(policy.Allows("example",null)||policy.Allows("example",id=>false)||!policy.Allows("example",id=>id=="knowledge.recipe")||!policy.Allows("other",null))throw new Exception("Reading gate incorrect");if(!policy.RequiresReading("knowledge.recipe")||policy.RequiresReading("other")||policy.RequiresReading(null))throw new Exception("Reading evidence whitelist incorrect");bool duplicate=false;try{RebirthRecipeDiscoveryPolicy.Read(XElement.Parse("<recipeDiscoveryPolicy version='1'><recipe name='example' requires_read='a'/><recipe name='example' requires_read='b'/></recipeDiscoveryPolicy>"));}catch(InvalidDataException){duplicate=true;}if(!duplicate)throw new Exception("Duplicate policy accepted");Console.WriteLine("PASS actual policy: empty default, exact knowledge requirement, unspecified recipe and duplicate rejection. No gameplay tested.");}
}